    20→package org.apache.druid.java.util.common;
    21→
    22→import org.apache.druid.utils.JvmUtils;
    23→
    24→import java.lang.invoke.MethodHandle;
    25→import java.lang.invoke.MethodHandles;
    26→import java.lang.invoke.MethodType;
    27→import java.security.ProtectionDomain;
    28→
    29→/**
    30→ * This utility class provides a thin runtime abstraction to pick between
    31→ * - sun.misc.Unsafe.defineClass in Java 8,
    32→ * - and MethodHandles.Lookup.defineClass in Java 9 and above,
    33→ * while still providing compile-time support for both Java 8 and Java 9+.
    34→ *
    35→ * See also {@link ByteBufferUtils}
    36→ */
    37→public class DefineClassUtils
    38→{
    39→  private static final MethodHandle DEFINE_CLASS;
    40→  private static final Exception DEFINE_CLASS_NOT_SUPPORTED_EXCEPTION;
    41→
    42→  static {
    43→    MethodHandle defineClass = null;
    44→    Exception exception = null;
    45→    try {
    46→      MethodHandles.Lookup lookup = MethodHandles.lookup();
    47→      if (JvmUtils.isIsJava9Compatible()) {
    48→        defineClass = defineClassJava9(lookup);
    49→      } else {
    50→        defineClass = defineClassJava8(lookup);
    51→      }
    52→    }
    53→    catch (ReflectiveOperationException | RuntimeException e) {
    54→      exception = e;
    55→    }
    56→    if (defineClass != null) {
    57→      DEFINE_CLASS = defineClass;
    58→      DEFINE_CLASS_NOT_SUPPORTED_EXCEPTION = null;
    59→    } else {
    60→      DEFINE_CLASS = null;
    61→      DEFINE_CLASS_NOT_SUPPORTED_EXCEPTION = exception;
    62→    }
    63→  }
    64→
    65→  /**
    66→   * "Compile" a MethodHandle that is equivalent to the following closure:
    67→   *
    68→   *  Class<?> defineClass(Class targetClass, String className, byte[] byteCode) {
    69→   *    MethodHandles.Lookup targetClassLookup = MethodHandles.privateLookupIn(targetClass, lookup);
    70→   *    return targetClassLookup.defineClass(byteCode);
    71→   *  }
    72→   */
    73→  private static MethodHandle defineClassJava9(MethodHandles.Lookup lookup) throws ReflectiveOperationException
    74→  {
    75→
    76→    // this is getting meta
    77→    MethodHandle defineClass = lookup.unreflect(MethodHandles.Lookup.class.getMethod("defineClass", byte[].class));
    78→    MethodHandle privateLookupIn = lookup.findStatic(
    79→        MethodHandles.class,
    80→        "privateLookupIn",
    81→        MethodType.methodType(MethodHandles.Lookup.class, Class.class, MethodHandles.Lookup.class)
    82→    );
    83→
    84→    // bind privateLookupIn lookup argument to this method's lookup
    85→    // privateLookupIn = (Class targetClass) -> privateLookupIn(MethodHandles.privateLookupIn(targetClass, lookup))
    86→    privateLookupIn = MethodHandles.insertArguments(privateLookupIn, 1, lookup);
    87→
    88→    // defineClass = (Class targetClass, byte[] byteCode) -> privateLookupIn(targetClass).defineClass(byteCode)
    89→    defineClass = MethodHandles.filterArguments(defineClass, 0, privateLookupIn);
    90→
    91→    // add a dummy String argument to match the corresponding JDK8 version
    92→    // defineClass = (Class targetClass, byte[] byteCode, String className) -> defineClass(targetClass, byteCode)
    93→    defineClass = MethodHandles.dropArguments(defineClass, 2, String.class);
    94→    return defineClass;
    95→  }
    96→
    97→  /**
    98→   * "Compile" a MethodHandle that is equilavent to:
    99→   *
   100→   *  Class<?> defineClass(Class targetClass, byte[] byteCode, String className) {
   101→   *    return Unsafe.defineClass(
   102→   *        className,
   103→   *        byteCode,
   104→   *        0,
   105→   *        byteCode.length,
   106→   *        targetClass.getClassLoader(),
   107→   *        targetClass.getProtectionDomain()
   108→   *    );
   109→   *  }
   110→   */
   111→  private static MethodHandle defineClassJava8(MethodHandles.Lookup lookup) throws ReflectiveOperationException
   112→  {
   113→    MethodHandle defineClass = lookup.findVirtual(
   114→        UnsafeUtils.theUnsafeClass(),
   115→        "defineClass",
   116→        MethodType.methodType(
   117→            Class.class,
   118→            String.class,
   119→            byte[].class,
   120→            int.class,
   121→            int.class,
   122→            ClassLoader.class,
   123→            ProtectionDomain.class
   124→        )
   125→    ).bindTo(UnsafeUtils.theUnsafe());
   126→
   127→    MethodHandle getProtectionDomain = lookup.unreflect(Class.class.getMethod("getProtectionDomain"));
   128→    MethodHandle getClassLoader = lookup.unreflect(Class.class.getMethod("getClassLoader"));
   129→
   130→    // apply getProtectionDomain and getClassLoader to the targetClass, modifying the methodHandle as follows:
   131→    // defineClass = (String className, byte[] byteCode, int offset, int length, Class class1, Class class2) ->
   132→    //   defineClass(className, byteCode, offset, length, class1.getClassLoader(), class2.getProtectionDomain())
   133→    defineClass = MethodHandles.filterArguments(defineClass, 5, getProtectionDomain);
   134→    defineClass = MethodHandles.filterArguments(defineClass, 4, getClassLoader);
   135→
   136→    // duplicate the last argument to apply the methods above to the same class, modifying the methodHandle as follows:
   137→    // defineClass = (String className, byte[] byteCode, int offset, int length, Class targetClass) ->
   138→    //   defineClass(className, byteCode, offset, length, targetClass, targetClass)
   139→    defineClass = MethodHandles.permuteArguments(
   140→        defineClass,
   141→        MethodType.methodType(Class.class, String.class, byte[].class, int.class, int.class, Class.class),
   142→        0, 1, 2, 3, 4, 4
   143→    );
   144→
   145→    // set offset argument to 0, modifying the methodHandle as follows:
   146→    // defineClass = (String className, byte[] byteCode, int length, Class targetClass) ->
   147→    //   defineClass(className, byteCode, 0, length, targetClass)
   148→    defineClass = MethodHandles.insertArguments(defineClass, 2, (int) 0);
   149→
   150→    // JDK8 does not implement MethodHandles.arrayLength so we have to roll our own
   151→    MethodHandle arrayLength = lookup.findStatic(
   152→        lookup.lookupClass(),
   153→        "getArrayLength",
   154→        MethodType.methodType(int.class, byte[].class)
   155→    );
   156→
   157→    // apply arrayLength to the length argument, modifying the methodHandle as follows:
   158→    // defineClass = (String className, byte[] byteCode1, byte[] byteCode2, Class targetClass) ->
   159→    //   defineClass(className, byteCode1, byteCode2.length, targetClass)
   160→    defineClass = MethodHandles.filterArguments(defineClass, 2, arrayLength);
   161→
   162→    // duplicate the byteCode argument and reorder to match JDK9 signature, modifying the methodHandle as follows:
   163→    // defineClass = (Class targetClass, byte[] byteCode, String className) ->
   164→    //   defineClass(className, byteCode, byteCode, targetClass)
   165→    defineClass = MethodHandles.permuteArguments(
   166→        defineClass,
   167→        MethodType.methodType(Class.class, Class.class, byte[].class, String.class),
   168→        2, 1, 1, 0
   169→    );
   170→
   171→    return defineClass;
   172→  }
   173→
   174→  static int getArrayLength(byte[] bytes)
   175→  {
   176→    return bytes.length;
   177→  }
   178→
   179→  public static Class defineClass(
   180→      Class<?> targetClass,
   181→      byte[] byteCode,
   182→      String className
   183→  )
   184→  {
   185→    if (DEFINE_CLASS == null) {
   186→      throw new UnsupportedOperationException(
   187→          "defineClass is not supported on this platform, "
   188→          + "because internal Java APIs are not compatible with this Druid version",
   189→          DEFINE_CLASS_NOT_SUPPORTED_EXCEPTION
   190→      );
   191→    }
   192→
   193→    try {
   194→      return (Class) DEFINE_CLASS.invokeExact(targetClass, byteCode, className);
   195→    }
   196→    catch (Throwable t) {
   197→      throw new UnsupportedOperationException("Unable to define specialized class: " + className, t);
   198→    }
   199→  }
   200→}
