    21→
    22→import com.fasterxml.jackson.annotation.JsonCreator;
    23→import com.fasterxml.jackson.annotation.JsonProperty;
    24→import com.fasterxml.jackson.annotation.JsonTypeName;
    25→import com.google.common.base.Preconditions;
    26→import com.google.common.base.Strings;
    27→import com.google.common.collect.ImmutableMap;
    28→import org.apache.druid.common.config.NullHandling;
    29→import org.apache.druid.java.util.common.StringUtils;
    30→import org.apache.druid.query.lookup.LookupExtractor;
    31→
    32→import javax.annotation.Nullable;
    33→import java.io.ByteArrayOutputStream;
    34→import java.io.IOException;
    35→import java.util.Collections;
    36→import java.util.List;
    37→import java.util.Map;
    38→import java.util.stream.Collectors;
    39→
    40→@JsonTypeName("map")
    41→public class MapLookupExtractor extends LookupExtractor
    42→{
    43→  private final Map<String, String> map;
    44→
    45→  private final boolean isOneToOne;
    46→
    47→  @JsonCreator
    48→  public MapLookupExtractor(
    49→      @JsonProperty("map") Map<String, String> map,
    50→      @JsonProperty("isOneToOne") boolean isOneToOne
    51→  )
    52→  {
    53→    this.map = Preconditions.checkNotNull(map, "map");
    54→    this.isOneToOne = isOneToOne;
    55→  }
    56→
    57→  @JsonProperty
    58→  public Map<String, String> getMap()
    59→  {
    60→    return ImmutableMap.copyOf(map);
    61→  }
    62→
    63→  @Nullable
    64→  @Override
    65→  public String apply(@Nullable String key)
    66→  {
    67→    String keyEquivalent = NullHandling.nullToEmptyIfNeeded(key);
    68→    if (keyEquivalent == null) {
    69→      // keyEquivalent is null only for SQL Compatible Null Behavior
    70→      // otherwise null will be replaced with empty string in nullToEmptyIfNeeded above.
    71→      return null;
    72→    }
    73→    return NullHandling.emptyToNullIfNeeded(map.get(keyEquivalent));
    74→  }
    75→
    76→  @Override
    77→  public List<String> unapply(@Nullable final String value)
    78→  {
    79→    String valueToLookup = NullHandling.nullToEmptyIfNeeded(value);
    80→    if (valueToLookup == null) {
    81→      // valueToLookup is null only for SQL Compatible Null Behavior
    82→      // otherwise null will be replaced with empty string in nullToEmptyIfNeeded above.
    83→      // null value maps to empty list when SQL Compatible
    84→      return Collections.emptyList();
    85→    }
    86→    return map.entrySet()
    87→              .stream()
    88→              .filter(entry -> entry.getValue().equals(valueToLookup))
    89→              .map(entry -> entry.getKey())
    90→              .collect(Collectors.toList());
    91→  }
    92→
    93→  @Override
    94→  @JsonProperty("isOneToOne")
    95→  public boolean isOneToOne()
    96→  {
    97→    return isOneToOne;
    98→  }
    99→
   100→  @Override
   101→  public byte[] getCacheKey()
   102→  {
   103→    try {
   104→      final ByteArrayOutputStream outputStream = new ByteArrayOutputStream();
   105→      for (Map.Entry<String, String> entry : map.entrySet()) {
   106→        final String key = entry.getKey();
   107→        final String val = entry.getValue();
   108→        if (!Strings.isNullOrEmpty(key)) {
   109→          outputStream.write(StringUtils.toUtf8(key));
   110→        }
   111→        outputStream.write((byte) 0xFF);
   112→        if (!Strings.isNullOrEmpty(val)) {
   113→          outputStream.write(StringUtils.toUtf8(val));
   114→        }
   115→        outputStream.write((byte) 0xFF);
   116→      }
   117→      return outputStream.toByteArray();
   118→    }
   119→    catch (IOException ex) {
   120→      // If ByteArrayOutputStream.write has problems, that is a very bad thing
   121→      throw new RuntimeException(ex);
   122→    }
   123→  }
   124→
   125→  @Override
   126→  public boolean canIterate()
   127→  {
   128→    return true;
   129→  }
   130→
   131→  @Override
   132→  public Iterable<Map.Entry<String, String>> iterable()
   133→  {
   134→    return map.entrySet();
   135→  }
   136→
   137→  @Override
   138→  public boolean equals(Object o)
   139→  {
   140→    if (this == o) {
   141→      return true;
   142→    }
   143→    if (o == null || getClass() != o.getClass()) {
   144→      return false;
   145→    }
   146→
   147→    MapLookupExtractor that = (MapLookupExtractor) o;
   148→
   149→    return map.equals(that.map);
   150→  }
   151→
   152→  @Override
   153→  public int hashCode()
   154→  {
   155→    return map.hashCode();
   156→  }
   157→
   158→}
